"""Exkurse: Verbindungen zwischen Lehrveranstaltungen. courses nennt die beteiligten LVs, topics die Karten, bei denen der Exkurs erscheint."""
LINKS = []
def L(id, title, courses, text, src, topics):
    LINKS.append(dict(id=id, title=title, courses=courses, text=text, src=src, topics=topics))

L("art12","Warum Wien eine eigene Mindestsicherung hat",["recht","matsi"],"Recht liefert den Grund: Armenwesen fällt unter Art 12 B-VG, also Grundsatzgesetz des Bundes und Ausführung durch die Länder. MatSi zeigt die Folgen: seit 2016 wieder Unterschiede je Bundesland, das Grundsatzgesetz 2019, die MA 40 als Landesbehörde.",[("r2",61),("f3",4),("msp",5)],["r-sh","r-bund","m-gesch"])
L("bescheid","Ein Bescheid, zwei Blickwinkel",["recht","matsi","faelle"],"MatSi sagt, was im Sozialzentrum zu tun ist: Referent*in, Servicestelle, Beschwerde. Recht erklärt, was der Bescheid ist und warum die Frist 4 Wochen beträgt. In den Fällen Herr K., Herr F. und Frau S. liegt genau dieser Bescheid auf dem Tisch.",[("msp",36),("r2",15),("r2",16),("c2",1),("c6",1),("cu",1)],["r-bescheid","r-beschwerde","m-bescheid","m-ablauf","f-c2","f-c6","f-cu"])
L("mahn","Vom Inkasso zur Exekution",["matsi","recht","faelle"],"MatSi beschreibt die Praxis der Schuldenspirale, Recht das Verfahren: Mahnklage, Zahlungsbefehl, Einspruch, Titel. Frau S. fürchtet wegen Inkasso das Gefängnis. Mit beiden LVs kannst du erklären, warum das falsch ist.",[("msp",61),("msp",62),("r2",32),("cu",1)],["m-inkasso","m-klage","r-mahn","r-exe","f-cu"])
L("exmin","Existenzminimum und Armutsgrenze",["recht","matsi","sopol"],"Recht rechnet den Grundbetrag 1.308 Euro, MatSi nennt das System, SoPol die Armutsgefährdung. Das Skript erwähnt die Forderung, das Existenzminimum bis zur Armutsgefährdungsschwelle anzuheben.",[("r2",38),("r2",39),("msp",65),("@armut",0)],["r-exmin","m-lohn","s-armut"])
L("delog","Delogierung von zwei Seiten",["matsi","recht"],"MatSi kennt den Ablauf und die Stellen: FAWOS, MA 11, MA 40. Recht liefert Zustellung, Tagsatzung, Fristen und Exekution. Wer die Räumungsklage nicht ernst nimmt, bekommt einen Versäumungstitel.",[("msk",78),("msp",28),("r2",43),("r2",34)],["m-delog","m-sicher","r-besitz","r-zust","r-exe"])
L("subsid","Subsidiarität hat Geschichte",["matsi","geschichte","sopol"],"In der WMS gilt: zuerst Arbeitskraft, Vermögen, Leistungen Dritter. Dasselbe Prinzip leitete die Armenfürsorge der Monarchie. SoPol ordnet es als Zug des konservativen Wohlfahrtsstaats ein.",[("msp",8),("a1",7),("zt",8),("s2",19)],["m-vor","gr-netze","s-regime","s-talos"])
L("heimat","Vom Heimatrecht zum Lebensmittelpunkt",["geschichte","matsi"],"Das Heimatrechtsgesetz 1863 knüpfte Versorgung an die Heimatgemeinde. Heute fragt die WWH nach dem Lebensmittelpunkt in Wien. Andere Sprache, ähnliche Frage: Wer gehört dazu, wer zahlt?",[("a1",7),("msp",45),("msk",91)],["m-ksow"])
L("gemeinde","Rotes Wien und Gemeindebau",["geschichte","matsi"],"Das Rote Wien sprach von einem allgemeinen Anrecht auf Fürsorge. Der Gemeindebau ist heute die wichtigste Ressource für leistbares Wohnen, die Soziale Wohnungsvergabe läuft dort. Wiener Wohnen vergibt erst neu, wenn Schulden beglichen sind.",[("rw",9),("msk",75),("msk",100)],["m-swv","m-rest"])
L("marienthal","Marienthal: damals und jetzt",["sopol","matsi"],"Einheit 4 erklärt die Folgen von Arbeitslosigkeit, Einheit 5 die Jobgarantie. In den Fällen zeigen Herr K. und Herr C. solche Biografien, und die WMS-Regeln zur Arbeitskraft setzen Aktivierung um.",[("s4",17),("s5",16),("msp",22),("c2",1),("c7",1)],["s-marienthal","s-garantie","m-arbeit"])
L("workfare","Workfare in den Regeln der WMS",["sopol","matsi","recht"],"SoPol nennt es Aktivierung und workfare statt welfare. Bei der MA 40 heißt es Kürzung um 25, 50 und 100 %, Sperre und Einstellung. Das Sozialhilfe-Grundsatzgesetz benennt die Funktionsfähigkeit des Arbeitsmarktes als Ziel.",[("s2",15),("s5",6),("msp",22),("msp",23),("r2",63)],["s-amp","s-entw","m-kuerz","r-sh"])
L("kategorien","Drei Einteilungen derselben Leistung",["matsi","recht","sopol"],"MatSi: Universal, Versicherung, Fürsorge. Recht: Versorgung, Versicherung, Sozialhilfe. SoPol: mit oder ohne Bedürftigkeitsprüfung, Geld oder Sachleistung. Dazu kommen Esping-Andersens Kategorien, die Valina und SoPol beide zeigen.",[("msp",2),("msp",3),("r2",61),("s3",13),("s2",19)],["m-kat","r-prinzipien","s-bed","s-geld"])
L("alg","Arbeitslosengeld dreimal",["recht","matsi","sopol"],"Alle drei LVs behandeln es. Recht: Voraussetzungen und Berufsschutz. MatSi: Anwartschaft, Tagsatz und Anrechnung auf die WMS. SoPol: passive Arbeitsmarktpolitik, Geschichte und Kritik.",[("r3",7),("msk",26),("s5",12)],["r-alv","r-nh","m-ams","s-alg","m-eink"])
L("zahl","Dieselbe Quote, andere Sicht: 0,6 %",["matsi","sopol"],"MatSi nennt 0,6 % Sozialhilfe an den Sozialausgaben. SoPol zeigt die Ausgaben nach Funktion und fragt, welche Leistungen am meisten diskutiert werden. Deine Notiz nennt genau diese: Mindestsicherung und Arbeitslosigkeit.",[("msp",6),("s3",12),("s3",21)],["m-zahlen","s-anteile"])
L("hhk","Familie als Haushalt",["matsi","sopol"],"Die Bedarfsgemeinschaft der WMS und das Haushaltsäquivalenzeinkommen in SoPol rechnen beide mit Größenvorteilen im Haushalt. Beide haben Probleme mit WGs: Seit 2026 gilt dort der Paarstandard.",[("msp",9),("msk",40),("s6",10)],["m-bg","m-ms","s-haeq"])
L("grundr","Grundrechte und Wohnen",["recht","matsi"],"MatSi nennt Wohnen als Grundrecht. In Recht lernst du: Grundrechte binden den Staat, und viele sind unter Vorbehalt. Wie durchsetzbar Wohnen ist, hängt also von einfachen Gesetzen und Förderungen ab.",[("msk",68),("f5",3)],["r-grund","m-wwh"])
L("sorge","Sorgearbeit im Fall",["sopol","matsi","faelle"],"Haug und Esping-Andersen-Kritik fragen nach unbezahlter Arbeit. Frau E. und Frau A. stellen dieselbe Frage konkret. Die WMS befreit von der Arbeitssuche nur bis zum 3. Lebensjahr ohne Betreuungsplatz.",[("s4",8),("s2",21),("msp",24),("c8",1),("cb",1)],["s-vier","s-kritik","f-c8","f-cb"])
L("schwarz","Schwarzarbeit: drei Folgen",["recht","matsi","faelle"],"Frau M. kellneriert schwarz. Recht: Rückforderung und Sperre beim AMS, Sozialbetrug. MatSi: Anzeigepflicht und Rückforderung bei der WMS. Herr M. und Herr B. zeigen die Spätfolgen: keine Anwartschaft, niedrige Pension.",[("r3",16),("r3",17),("msk",50),("c5",1),("c3",1),("c4",1)],["r-alv","m-ruhen","f-c5"])
L("eu","EU-Recht im Sozialzentrum",["recht","matsi"],"Recht zeigt Richtlinien und Verordnungen. In der MatSi kommen sie als Erwerbstätigeneigenschaft und Daueraufenthalt zurück: Darum geht es bei Herrn F. und bei der Partnerin von Herrn C.",[("f2",3),("msk",36),("c6",1),("c7",1)],["r-eurecht","m-eu"])
L("selbst","Gescheiterte Selbstständigkeit",["matsi","sopol","faelle"],"MatSi nennt sie als Überschuldungsgrund. SoPol zeigt, warum Selbstständige außerhalb des Normalarbeitsverhältnisses wenig Schutz haben. Frau K. zeigt, was das in einem Leben heißen kann.",[("msp",58),("s2",24),("c9",1)],["m-gruende","s-krise","f-c9"])
L("gericht","Recht gegen Gerechtigkeit",["recht","sopol"],"SoPol fragt: Was ist gerecht, Bedarf, Leistung oder Besitz? Recht sagt: Auch als ungerecht empfundenes Recht gilt. Beide Fragen stellen sich, wenn ein Klient sagt: Das ist doch nicht fair.",[("s2",4),("f3",3)],["r-gerecht","s-gerecht"])
L("erbe","Erbschaften im Vergleich",["sopol","matsi"],"Bei Reichen sagt SoPol: Eine Erbschaftssteuer gibt es seit 2008 nicht mehr. In der WMS gilt: Wer ein Erbe nicht antritt, wird gekürzt, und wer etwas erbt, leistet Kostenersatz. Das zeigt zwei sehr unterschiedliche Blicke auf leistungslose Einkommen.",[("s6",14),("msk",50),("msk",51)],["s-vorschlag","s-verm","m-verm"])
L("raster","Raster und Fachwissen",["faelle","matsi","recht","sopol"],"Im Raster steckt alles: Auftrag und Ressourcen aus MatSi, Fristen und Rechtsmittel aus Recht, Hypothesen zu Ursachen aus SoPol. Punkte mit dem Rechts- oder SoPol-Blick sind in der Fallwerkstatt markiert.",[("cr",1)],["f-raster"])
L("kbg","Kinderbetreuungsgeld: Beratung und Recht",["matsi","recht"],"MatSi zeigt, was du in der Beratung prüfst: Variante, 182-Tage-Frist, Wochengeld zuerst, Krankenversicherung endet mit dem Bezug. Recht erklärt die Regeln dahinter: gebundener Tagesbetrag, Änderungsantrag, Rückforderung bei überschrittener Zuverdienstgrenze. Für die WMS ist KBG anrechenbar, bei der Exekution das pauschale KBG unpfändbar.",[("msk",18),("r3",26),("r3",27),("r3",30),("msk",45),("msp",63)],["m-kbg","m-kbgvar","m-kbgpraxis","r-kbgr","r-kbgkonto","r-kbgrueck"])
L("sperre","Eine AMS-Sperre trifft doppelt",["recht","matsi"],"Recht: Wer eine zumutbare Arbeit verweigert, verliert das Arbeitslosengeld für mindestens 6 Wochen. MatSi: Die MA 40 rechnet das gesperrte Geld fiktiv an und kann wegen fehlenden Einsatzes der Arbeitskraft zusätzlich kürzen. Darum ist bei jeder AMS-Sperre auch die Mindestsicherung Thema.",[("r3",10),("msk",46),("msk",49)],["r-sperre","m-fiktiv","m-eink","m-kuerz"])
L("teilzeit","Teilzeit, Scheidung und das zweite Netz",["sopol","matsi"],"SoPol erklärt, warum der konservative Sozialstaat anfällig für Teilzeit und Scheidungen ist. MatSi zeigt die Folge: 75 % der WMS-Bedarfsgemeinschaften bekommen die Mindestsicherung als Ergänzung zu einem zu kleinen Einkommen.",[("s2",23),("msp",6)],["s-at","s-prekaer","m-zahlen","m-ms"])
